"""Before/after evidence, generated by diffing a pre-write snapshot against
the live site.

The 'before' side is never re-derived from memory or from the dry run: it is
read back out of the snapshot that `apply` wrote before its first write, so the
evidence and the rollback data are the same artefact. If one is wrong, the
other is too, and both fail loudly rather than quietly disagreeing.
"""
from __future__ import annotations

import io
import json
from datetime import datetime, timezone
from pathlib import Path

TICK = "`"

FIELD_LABELS = {
    "post_title": "Page title",
    "rank_math_title": "SEO title (rendered)",
    "rank_math_description": "Meta description (rendered)",
}


def _code(text: str) -> str:
    text = (text or "").replace("\n", " ").strip()
    # SEO titles legitimately contain "|", which would otherwise be read as a
    # markdown cell separator and silently split the row.
    text = text.replace("|", "\\|")
    return TICK + (text or "(empty)") + TICK


def _row(field: str, before: str, after: str) -> str:
    label = FIELD_LABELS.get(field, field)
    mark = "unchanged" if (before or "").strip() == (after or "").strip() else "changed"
    return f"| {label} | {_code(before)} | {_code(after)} | {mark} |\n"


def build(snapshot_dir: Path, state: dict, audits: list) -> str:
    snapshot, provenance = compose_before(snapshot_dir)
    out = io.StringIO()
    w = out.write

    w("# Before / after evidence\n\n")
    w("Generated " + datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
      + ".\n\n")
    w("The **before** column is read from the snapshots written before each "
      "write, not reconstructed afterwards. The **after** column is read live "
      "from the site at generation time. Rendered values are taken from the "
      "delivered HTML, not the database, so a value that is stored but never "
      "output would show as unchanged.\n\n")
    w("Provenance of the before-state:\n\n")
    for section, name in sorted(provenance.items()):
        w("- " + _code(section) + " from " + _code("snapshots/" + name) + "\n")
    w("\n")

    changed = 0
    total = 0

    w("## Global\n\n")
    w("| Field | Before | After | |\n|---|---|---|---|\n")
    before_title = snapshot.get("site_title", "")
    after_title = state.get("site_title", "")
    w(_row("Site title", before_title, after_title))
    total += 1
    if before_title.strip() != after_title.strip():
        changed += 1
    w("\n")

    w("## Pages\n\n")
    for key, after_page in state.get("pages", {}).items():
        before_page = snapshot.get("pages", {}).get(key, {})
        w("### " + key.replace("_", " ").title()
          + "  \n" + _code(after_page.get("link", "")) + "\n\n")
        w("| Field | Before | After | |\n|---|---|---|---|\n")
        for field in ("post_title", "rank_math_title", "rank_math_description"):
            before = before_page.get(field, "")
            after = after_page.get(field, "")
            w(_row(field, before, after))
            total += 1
            if (before or "").strip() != (after or "").strip():
                changed += 1
        w("\n")

    before_menu = snapshot.get("menu_items") or {}
    after_menu = state.get("menu_items") or {}
    if before_menu or after_menu:
        w("## Navigation (Primary Header)\n\n")
        if not before_menu:
            w("> Menu state was not captured in any snapshot for this session, "
              "so no before-value can be evidenced here. Reported as "
              "uncaptured rather than shown as empty.\n\n")
        # Match items by WordPress menu-item ID so a renamed item reads as one
        # change, not as a deletion plus an addition.
        before_by_id = {i: label for label, i in before_menu.items()}
        after_by_id = {i: label for label, i in after_menu.items()}
        w("| Item ID | Before | After | |\n|---|---|---|---|\n")
        for item_id in sorted(set(before_by_id) | set(after_by_id)):
            was = before_by_id.get(item_id, "")
            now = after_by_id.get(item_id, "")
            if not was:
                mark = "not captured"
            elif was.strip() == now.strip():
                mark = "unchanged"
            else:
                mark = "changed"
            w("| " + str(item_id) + " | " + _code(was) + " | " + _code(now)
              + " | " + mark + " |\n")
            total += 1
            if mark == "changed":
                changed += 1
        w("\n")

    w("## Site conditions after the run\n\n")
    w("| Page | Placeholders remaining | Images without alt | Dead `#` links | Forms |\n")
    w("|---|---|---|---|---|\n")
    for a in audits:
        w("| " + a.label + " | " + str(sum(a.placeholders.values()))
          + " | " + str(len(a.images_missing_alt)) + " of " + str(a.image_count)
          + " | " + str(len(a.empty_href_links))
          + " | " + str(a.forms) + " |\n")
    w("\nThese are reported, not fixed. Long-form content placement, image alt "
      "text, and link destinations have no approved values supplied; see the "
      "exception report.\n\n")

    w("---\n\n**" + str(changed) + " of " + str(total)
      + " tracked fields changed.** Every change traces to an Approved value "
        "in the Site Variable Sheet; the dry run recorded each one before it "
        "was written.\n")

    return out.getvalue()


def latest_snapshot(directory: Path) -> Path:
    """The EARLIEST snapshot is the true 'before' for a multi-run session."""
    snaps = sorted(directory.glob("*.json"))
    if not snaps:
        raise FileNotFoundError("no snapshots found; run `apply` first")
    return snaps[0]


def compose_before(directory: Path) -> tuple[dict, dict[str, str]]:
    """Assemble the before-state across every snapshot in the session.

    A snapshot only contains the sections the code captured at the time it was
    taken. Reading a section that is absent as "empty" would render a field
    that was never captured as though it did not exist -- evidence that is
    confidently wrong. Instead, walk snapshots oldest to newest and take each
    section from the first snapshot that actually carries it, recording the
    provenance so the report can state where each half came from.
    """
    snaps = sorted(directory.glob("*.json"))
    if not snaps:
        raise FileNotFoundError("no snapshots found; run `apply` first")

    before: dict = {}
    provenance: dict[str, str] = {}
    for path in snaps:
        data = json.loads(path.read_text(encoding="utf8"))
        for section in ("site_title", "pages", "menu_items"):
            if section in before and before[section]:
                continue
            value = data.get(section)
            if value:
                before[section] = value
                provenance[section] = path.name
    return before, provenance
